// ============================================================
// StreamForge Mock Data
// ============================================================
//
// IMPORTANT:
//
// workerCount and partitionCount are ONLY for frontend testing.
//
// The real StreamForge deployment will eventually provide
// worker/partition information through FastAPI.
//
// Change these values to test different cluster sizes.
//
// Example:
//
// 20 workers / 20 partitions
// 50 workers / 50 partitions
// 100 workers / 50 partitions
//
// The UI itself does not have a fixed worker limit.
// ============================================================


/* ============================================================
   TEST CONFIGURATION
   ============================================================ */

export const testConfig = {
  workerCount: 20,
  partitionCount: 20,
};


/* ============================================================
   SYSTEM METRICS
   ============================================================ */

export const systemMetrics = {
  eventsPerSecond: 98420,

  activeWorkers: testConfig.workerCount,
  totalWorkers: testConfig.workerCount,

  activePartitions: testConfig.partitionCount,
  totalPartitions: testConfig.partitionCount,

  processingLatency: 24,

  consumerLag: 1284,

  failedWorkers: 0,

  uptime: "2h 34m",

  throughputTrend: "+4.2%",

  latencyTrend: "-3.1%",
};


/* ============================================================
   WORKER GENERATOR
   ============================================================ */

export const workers = Array.from(
  {
    length: testConfig.workerCount,
  },

  (_, index) => {

    const workerNumber = index + 1;

    return {
      id: `worker-${String(workerNumber).padStart(2, "0")}`,

      name: `Worker ${String(workerNumber).padStart(2, "0")}`,

      status: "healthy",

      eventsPerSecond:
        7000 + Math.floor(Math.random() * 2000),

      lag:
        20 + Math.floor(Math.random() * 20),

      cpu:
        35 + Math.floor(Math.random() * 20),

      memory:
        50 + Math.floor(Math.random() * 20),

      partitions: [],
    };
  }
);


/* ============================================================
   PARTITION GENERATOR
   ============================================================ */

export const partitions = Array.from(
  {
    length: testConfig.partitionCount,
  },

  (_, index) => {

    const assignedWorker =
      workers.length > 0
        ? workers[index % workers.length]
        : null;

    return {
      id: index,

      name:
        `Partition ${String(index).padStart(2, "0")}`,

      status: "active",

      lag:
        20 + (index * 7) % 20,

      workerId:
        assignedWorker
          ? assignedWorker.id
          : null,
    };
  }
);


/* ============================================================
   CONNECT PARTITIONS TO WORKERS
   ============================================================ */

partitions.forEach((partition) => {

  if (!partition.workerId) {
    return;
  }

  const worker = workers.find(
    (item) => item.id === partition.workerId
  );

  if (worker) {
    worker.partitions.push(
      partition.id
    );
  }
});


/* ============================================================
   THROUGHPUT HISTORY
   ============================================================ */

export const throughputHistory = [
  {
    time: "10:00",
    value: 78200,
  },

  {
    time: "10:01",
    value: 81600,
  },

  {
    time: "10:02",
    value: 85400,
  },

  {
    time: "10:03",
    value: 90100,
  },

  {
    time: "10:04",
    value: 93200,
  },

  {
    time: "10:05",
    value: 91800,
  },

  {
    time: "10:06",
    value: 95600,
  },

  {
    time: "10:07",
    value: 98420,
  },
];


/* ============================================================
   STREAM PROCESSING PIPELINE
   ============================================================ */

export const pipeline = {

  inputTopic:
    "truck-telemetry",

  outputTopic:
    "truck-temperature-averages",

  filter:
    "temperature > 0",

  window:
    "5-minute",

  processor:
    "Bytewax / Faust",

  stateStore:
    "RocksDB",

  metrics:
    "Prometheus",
};


/* ============================================================
   TOPOLOGY STATUS
   ============================================================ */

export const topologyStatus = {

  kafka: {
    status: "healthy",

    partitions:
      testConfig.partitionCount,
  },

  processor: {
    status: "healthy",

    workers:
      testConfig.workerCount,
  },

  rocksdb: {
    status: "healthy",
  },

  prometheus: {
    status: "healthy",
  },
};
